/// <summary>
/// getJournalLines' request (DIRECT transfer mode). Location range blank means the whole journal,
/// or whatever range ClaimToken holds.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountDirectLinesRequest
{
    DataAreaId      dataAreaId;
    InventJournalId journalId;
    str             claimToken;
    str             locationFrom;
    str             locationTo;
    str             userId;
    real            fromLine;

}

Method.Source:
[DataMemberAttribute('FromLine')]
public real parmFromLine(real _value = fromLine)
{
    fromLine = _value;
    return fromLine;
}

[DataMemberAttribute('UserId')]
public str parmUserId(str _value = userId)
{
    userId = _value;
    return userId;
}

[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('JournalId')]
public InventJournalId parmJournalId(InventJournalId _value = journalId)
{
    journalId = _value;
    return journalId;
}

[DataMemberAttribute('ClaimToken')]
public str parmClaimToken(str _value = claimToken)
{
    claimToken = _value;
    return claimToken;
}

[DataMemberAttribute('LocationFrom')]
public str parmLocationFrom(str _value = locationFrom)
{
    locationFrom = _value;
    return locationFrom;
}

[DataMemberAttribute('LocationTo')]
public str parmLocationTo(str _value = locationTo)
{
    locationTo = _value;
    return locationTo;
}
